import json
from pathlib import Path
root=Path('/home/ubuntu/oracle-daily'); p=json.loads((root/'reports/comprehensive_validation.json').read_text())
s=p['stages']; q=s['stage1_data_quality']; cal=s['stage3_calibration']; ens=s['stage4_market_ensemble']; ev=s['stage6_ev_clv']
def pct(x): return 'غير متاح' if x is None else f'{x*100:.2f}%'
def met(x): return f"N={x.get('n',0)}, Accuracy={pct(x.get('accuracy'))}, Brier={x.get('brier','—')}, Log Loss={x.get('logLoss','—')}"
lines=['# التقرير الشامل للتحقق من ORACLE مع OddsHarvester','', '## 1. الملخص التنفيذي','', 'تم تنفيذ خط تحقق زمني من سبع مراحل على عينة OddsHarvester تحتوي على أسعار حركة مؤرخة قبل kickoff. النتيجة الحالية لا تبرر تجميد نموذج أو اعتبار EV إشارة قابلة للتنفيذ؛ العينة صغيرة، وتغطية المطابقة غير مكتملة، وCLV الحقيقي غير متاح.', '', f"- السجلات الخام: **{q['records']}**.", f"- المطابقة المستخدمة: **{s['stage2_full_season_status']['matched_records']}**.", f"- التغطية: **{pct(s['stage2_full_season_status']['coverage'])}**.", f"- الأسعار قبل kickoff: **{s['stage2_full_season_status']['preKickoffQuotes']}**.", f"- درجة المعايرة الزمنية: temperature={cal['temperature']}.", f"- الوزن المختار في العينة: سوق 100% ضمن شبكة الاختبار، وليس قرارًا نهائيًا.", '', '## 2. جودة البيانات والتنظيف', '', f"- المدى الزمني: {q['date_min']} إلى {q['date_max']}.", f"- عدد الأيام الفريدة: {q['unique_dates']}.", f"- متوسط الأهداف: محلي {q['mean_home_goals']:.2f}، ضيف {q['mean_away_goals']:.2f}.", f"- وسيط عدد الشركات: {q['bookmakers_median']:.0f}.", f"- أقل عدد شركات: {q['bookmakers_min']}.", f"- أعلى عدد أهداف لفريق في مباراة: {q['max_team_goals']}.", '', 'تم تطبيق تطبيع أسماء الفرق في مشغل الاختبار، لكن بقيت سجلات غير مطابقة؛ يجب رفع التغطية إلى 95% على الأقل قبل الاستنتاج النهائي.', '', '## 3. اختبار الموسم الكامل والأسعار قبل kickoff', '', 'الاختبار الكامل قيد جمع odds-history. العينة الحالية ليست موسمًا كاملًا، لذلك وُسمت النتائج مؤقتًا `sample_only`. يختار المشغل آخر سعر تاريخي قبل kickoff لكل شركة ثم يأخذ الوسيط بين الشركات.', '', '## 4. معايرة الاحتمالات', '', f"الطريقة: temperature scaling زمني؛ تدريب على {cal['train_n']} مباراة واختبار على {cal['test_n']} مباراة.", '', '| الحالة | Brier | Log Loss | Accuracy |', '|---|---:|---:|---:|']
for label,k in [('خام','raw_test'),('بعد المعايرة','calibrated_test')]:
 x=cal[k]; lines.append(f"| {label} | {x.get('brier','—')} | {x.get('logLoss','—')} | {pct(x.get('accuracy'))} |")
lines += ['', 'هذه المعايرة استكشافية بسبب صغر عينة التدريب، وليست إثباتًا ضد overfitting.', '', '## 5. Ensemble وتعلم وزن السوق', '', 'تم اختبار شبكة أوزان زمنية بدل ادعاء استخدام Gradient Boosting على عينة صغيرة. أفضل نقطة اختبارية كانت:', '', f"- وزن النموذج: {ens['selected']['model_weight']*100:.0f}%.", f"- وزن السوق: {(1-ens['selected']['model_weight'])*100:.0f}%.", f"- Log Loss الاختباري: {ens['selected']['test']['logLoss']:.4f}.", '', 'هذا لا يعني أن السوق يجب أن يحل محل ORACLE؛ يعني فقط أن السوق كان المرجع الأقوى في العينة الحالية.', '', '## 6. Ablation Study', '', 'المتاح حاليًا هو Ablation على المكونات:', '', '| المكوّن | النتيجة |', '|---|---|']
for name,k in [('Elo','elo'),('Dixon–Coles','dixon_coles'),('Ensemble','ensemble')]:
 x=s['stage5_ablation']['component_ablation'][k]; lines.append(f'| {name} | {met(x)} |')
lines += ['', 'أما إزالة H2H وForm وStandings كلٌّ على حدة فتحتاج التقاط متغيرات النموذج الخام لكل مباراة. لم يتم اختلاق هذه المقارنة من نتائج المكونات.', '', '## 7. EV وCLV خارج العينة', '', 'تم حساب EV على الاختبار الزمني، مع Bootstrap للـ ROI. لا يتوفر CLV حقيقي لأننا لا نملك snapshot مستقلاً لسعر الإغلاق من مصدر مختلف أو وقت لاحق موثق.', '', '| العتبة | الرهانات | ROI | مجال Bootstrap 95% |', '|---:|---:|---:|---:|']
for k,v in ev['ev_thresholds'].items(): lines.append(f"| {k} | {v.get('bets',0)} | {pct(v.get('roi'))} | {pct(v.get('ci95_low'))} إلى {pct(v.get('ci95_high'))} |")
lines += ['', '## 8. التجميد والمراقبة', '', '**لم يتم تجميد النموذج**. مؤشرات إعادة التدريب:', '', '- ارتفاع Log Loss المتحرك 20% عن خط الأساس.', '- ارتفاع Brier المتحرك 15%.', '- هبوط مطابقة الفرق تحت 95%.', '- غياب أسعار pre-kickoff أو timestamps.', '- فجوة معايرة أكبر من 8 نقاط مئوية.', '', 'يُعاد التدريب أو المراجعة إذا استمرت الإشارة على 50 مباراة مقيمة.', '', '## 9. الخلاصة والتوصيات', '', '1. انتظار ملف الموسم الكامل بعد انتهاء جمع odds-history.', '2. إصلاح قاموس أسماء الفرق وإظهار تقرير المطابقة لكل سجل.', '3. إعادة تشغيل المعايرة ودمج السوق على موسم كامل ثم موسم خارج العينة.', '4. إضافة التقاط صريح لنسخ no-H2H/no-Form/no-Standings لإكمال Ablation المطلوب.', '5. إضافة closing snapshot مستقل قبل ادعاء CLV.', '6. عدم تحويل EV الموجب إلى توصية أو تنفيذ؛ العينة الحالية لا تثبت قيمة موجبة.', '', '## 10. الملفات والمنهجية', '', '- مشغل الأسعار التاريخية: `tools/odds_history_backtest.js`.', '- محلل المراحل السبع: `tools/comprehensive_validation.py`.', '- نتيجة JSON: `reports/comprehensive_validation.json`.', '- بيانات OddsHarvester المؤرخة: `data/raw/epl_2024_2025_odds_history_sample.json`.']
(root/'reports/comprehensive_validation.md').write_text('\n'.join(lines)+'\n')
# simple static dashboard
html='''<!doctype html><meta charset="utf-8"><title>ORACLE Monitoring</title><style>body{font-family:system-ui;max-width:900px;margin:2rem auto;padding:0 1rem;background:#f8fafc;color:#0f172a}section{background:white;padding:1rem;margin:1rem 0;border-radius:12px;box-shadow:0 2px 8px #0001}table{width:100%;border-collapse:collapse}td,th{padding:.6rem;border-bottom:1px solid #e2e8f0;text-align:start}.warn{color:#b45309}</style><h1>ORACLE Monitoring</h1><p class="warn">حالة النموذج: غير مجمّد — العينة الحالية استكشافية.</p><section><h2>جودة البيانات</h2><pre id="quality"></pre></section><section><h2>إشارات الإنذار</h2><ul><li>Coverage أقل من 95%</li><li>Pre-kickoff quotes غير مكتملة</li><li>Log Loss/Brier متحركان أعلى من خط الأساس</li><li>فجوة معايرة أكبر من 8%</li></ul></section><script>fetch('comprehensive_validation.json').then(r=>r.json()).then(x=>document.querySelector('#quality').textContent=JSON.stringify(x.stages.stage1_data_quality,null,2))</script>'''
(root/'reports/monitoring_dashboard.html').write_text(html)
